    fn get_event_name(event: Self::Event) -> &'static str {
        match event {
            ASendReachesOnlyWhatItsTargetNamesEvent::Bare => "bare",
            ASendReachesOnlyWhatItsTargetNamesEvent::DoneInvoke => "done.invoke",
            ASendReachesOnlyWhatItsTargetNamesEvent::ErrorCommunication => "error.communication",
            ASendReachesOnlyWhatItsTargetNamesEvent::ErrorExecution => "error.execution",
            ASendReachesOnlyWhatItsTargetNamesEvent::Hello => "hello",
            ASendReachesOnlyWhatItsTargetNamesEvent::Lost => "lost",
            ASendReachesOnlyWhatItsTargetNamesEvent::Ping => "ping",
            ASendReachesOnlyWhatItsTargetNamesEvent::Pong => "pong",
            ASendReachesOnlyWhatItsTargetNamesEvent::Refused => "refused",
            ASendReachesOnlyWhatItsTargetNamesEvent::Settle => "settle",
            ASendReachesOnlyWhatItsTargetNamesEvent::Null => "",
        }
    }

    fn get_event_from_name(name: &str) -> Option<Self::Event> {
        match name {
            "bare" => Some(ASendReachesOnlyWhatItsTargetNamesEvent::Bare),
            "done.invoke" => Some(ASendReachesOnlyWhatItsTargetNamesEvent::DoneInvoke),
            "error.communication" => {
                Some(ASendReachesOnlyWhatItsTargetNamesEvent::ErrorCommunication)
            }
            "error.execution" => Some(ASendReachesOnlyWhatItsTargetNamesEvent::ErrorExecution),
            "hello" => Some(ASendReachesOnlyWhatItsTargetNamesEvent::Hello),
            "lost" => Some(ASendReachesOnlyWhatItsTargetNamesEvent::Lost),
            "ping" => Some(ASendReachesOnlyWhatItsTargetNamesEvent::Ping),
            "pong" => Some(ASendReachesOnlyWhatItsTargetNamesEvent::Pong),
            "refused" => Some(ASendReachesOnlyWhatItsTargetNamesEvent::Refused),
            "settle" => Some(ASendReachesOnlyWhatItsTargetNamesEvent::Settle),
            _ => None,
        }
    }

    fn get_state_name(state: Self::State) -> &'static str {
        match state {
            ASendReachesOnlyWhatItsTargetNamesState::Done => "done",
            ASendReachesOnlyWhatItsTargetNamesState::Run => "run",
        }
    }

