    // recorded configuration back into the `StateChain` `enter_at` takes.
    fn get_state_from_name(name: &str) -> Option<Self::State> {
        match name {
            "done" => Some(ASendReachesOnlyWhatItsTargetNamesState::Done),
            "run" => Some(ASendReachesOnlyWhatItsTargetNamesState::Run),
            _ => None,
        }
    }

